import re

def f(inputs):
    results = []

    for n, expression in inputs:
        if n == 0:
            break
        # Remove any whitespace from the expression
        expression = expression.replace(" ", "")

        # Use regular expression to extract numbers and operators
        tokens = re.findall(r"\d+|\+|-|\*|/|\(|\)", expression)

        # Evaluate the expression
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in "+-*/":
                b = stack.pop()
                a = stack.pop()
                if token == "+":
                    stack.append(a + b)
                elif token == "-":
                    stack.append(a - b)
                elif token == "*":
                    stack.append(a * b)
                elif token == "/":
                    stack.append(a // b)
            elif token == "(":
                stack.append(token)
            elif token == ")":
                temp = []
                while stack[-1]!= "(":
                    temp.append(stack.pop())
                stack.pop()  # Remove the "("
                temp.reverse()
                stack.append(calculate(temp))

        results.append(stack[0])

    return results


def calculate(tokens):
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                stack.append(a // b)
    return stack[0]

inputs = [(3, "(1+2)*3+3"), (2, "1*1*1+1*1*1"), (587, "1*(2*3*4)+5+((6+7*8))*(9)"), (0, "")]
print(f(inputs))  # Output: [16, 2, 587]
```

